    def collect_snapshot(self, **kwargs):
        """ This function collects snapshot and saves in a file in execution_logs
            :param coverage: Snapshot coverage (Full or Minor).
            :param force : Force snapshot collection
            :param timeout: Time to wait for positive procedure result
            :param alias: Name of execution context
        """
        coverage = kwargs.get("coverage", 'Full')
        force = kwargs.get("force", True)
        regexp_filter = kwargs.get('regexp_filter', None)
        reason = kwargs.get('reason', None)
        cells = kwargs.get('cells', None)
        file_extension = kwargs.get("file_extension", 'zip')
        timeout = kwargs.get("timeout", 360)
        alias = kwargs.get("alias", 'default')

        tstamp = time.time()
        tstamp = datetime.datetime.fromtimestamp(tstamp).strftime('%d%m%y_%H%M%S')
        logger.debug("tstamp :: {}".format(str(tstamp)))
        target_file = 'execution_logs/{}'.format('tech_snapshot_{}.{}'.format(tstamp,
                                                                              file_extension))
        logger.debug("target file :: {}".format(target_file))
        if not os.path.exists(os.path.dirname(target_file)):
            os.makedirs(os.path.dirname(target_file))
        logger.debug("Collecting snap shot..")
        self.factory.admin.collect_snapshot(target_file, coverage=coverage, force=force,
                                            regexp_filter=regexp_filter, reason=reason,
                                            cells=cells, timeout=timeout, connection=alias)
        return target_file

    @check_rat
    def reset_bts(self, **kwargs):
        """ Resets BTS
            :param verify_bts: Boolean. to check if BTS status should be onAir or not
            :param req_rat: which RATs status to be checked.
            :param wait_for: Time to wait(seconds) before checking for status after reset
            :param alias: Name of execution context
        """
        verify_bts = kwargs.pop("verify_bts", True)
        req_rat = kwargs.pop("req_rat", 'all')
        should_be_onair = kwargs.pop("should_be_onair", True)
        wait_for = kwargs.pop("wait_for", 300)
        alias = kwargs.get("alias", 'default')

        logger.debug("performing site reset..")
        self.factory.admin.reset_site(timeout=300, connection=alias)
        # Reset().verify_bts_reset_internal(**kwargs)
        logger.debug("performing ping test...")
        self._perform_ping_test(alias)
        if verify_bts:
            logger.debug("verifying bts status...")
            CellOperations().verify_bts_status(req_rat=req_rat, should_be_onair=should_be_onair,
                                               wait_for=wait_for, alias=alias)

