    def _find_build(self, wft_profile):
        config_base_path = get_config_variable(['config_base_path'])
        filters_file = get_resource_file('wft_filters.json', config_base_path)
        latest_buildnum, download_url, package_template = self.build_download.find_latest_build(filters_file,
                                                                                                wft_profile)
        logger.info('latest_buildnum: {}, download_url: {}, package_template {}'.format(latest_buildnum, download_url,
                                                                                        package_template))
        return download_url, latest_buildnum, package_template

    def _is_current_build_not_same_as_latest_build(self, latest_build, alias):

        bts_status = self.factory.admin.get_bts_statuses(connection=alias)
        if bts_status['proceduralState'] == "NotCommissioned":
            current_build_from_admin = self._get_build_name_on_bts(alias).strip()
            logger.info('latest_build {} current_build_from_admin {}'.format(latest_build, current_build_from_admin))
        else:
            sw_info = self.factory.admin.get_software_info(connection=alias)
            current_build_from_admin = sw_info['Active SW version']
            logger.info('latest_build {} current_build_from_admin {}'.format(latest_build, current_build_from_admin))

        current_build_num_from_admin = self._get_build_num_from_name(current_build_from_admin)
        latest_build_num = self._get_build_num_from_name(latest_build)
        if current_build_num_from_admin != latest_build_num:
            return True
        else:
            return False
        # current_build_from_admin = self._get_build_name_on_bts(alias, "active").strip()
        # logger.info('latest_build {} current_build_from_admin {}'.format(latest_build,
