    def _get_build_num_from_name(self, build):
        # decode the type of build from byte to str
        try:
            build = decode_str(build)
        except Exception as error:
            logger.debug("Ignoring {}, as variable 'build' data type is not unicode.".format(str(error)))
        separators = r'(\.|-|_)'
        extracted_num_seq = re.findall(r'{}(\d+)'.format(separators), build)
        # Sample result [('_', '9982'), ('_', '190807'), ('_', '000309')]
        extracted_num_seq = [str(int(item[1])) for item in extracted_num_seq]
        extracted_num_seq = extracted_num_seq[-2]+'_'+extracted_num_seq[-1]
        logger.info('extracted_num_seq: {}'.format(extracted_num_seq))
        return extracted_num_seq

        # build_strings = current_build.split('.')[0].split('_')
        # build_num = build_strings[-1] + build_strings[-2]
        # return build_num

    def _get_build_name_from_package(self, package):
        build_name = package.split("_release")[0]
        return build_name

    def _get_build_name_on_bts(self, alias, partition="active"):
        dut = global_vars.alias_dut_dict[alias]
        ip = get_config_variable([dut, 'ip'])
        user = get_config_variable([dut, 'user'])
        password = get_config_variable([dut, 'password'])
        if partition == "active":
            build = 'run'
        else:
            build = 'stb'

        filename = subprocess.check_output(
            'sshpass -p {password} ssh {user}@{ip} ls /ffs/{build} | grep Target -m 1'.format(
                ip=ip, user=user, password=password, build=build), shell=True)
        current_build = filename[9:-5].strip()
        return current_build

    def _perform_ping_test(self, alias):
        ping_timeout = 10
        dut = global_vars.alias_dut_dict[alias]
        bts_lmp_ip = get_config_variable([dut, 'ip'])
        command = 'ping -c 1 {}'.format(bts_lmp_ip)
        if dut == "chained_bts":
            logger.info("testing ping for chained bts")
            ip = get_config_variable([dut, 'remote_lmp_ip'])
            username = get_config_variable([dut, 'remote_lmp_user'])
            password = get_config_variable([dut, 'remote_lmp_password'])
            comm = Communicator()

            for ping_attempt in range(ping_timeout):
                try:
                    comm.execute_command_remotely(ip, username, password, command, port=22)
                except Exception as comm_e:
                    logger.debug("Retrying ping. Ignoring exception : {}".format(comm_e))
                else:
                    logger.info('ping successful after {} seconds'.format(ping_attempt))
                    break
            else:
                raise PingTestFailedException('ping unsuccessful after {} seconds'.format(
                    ping_timeout))
        else:
            for ping_attempt in range(ping_timeout):
                try:
                    subprocess.check_output(command, shell=True)
                except subprocess.CalledProcessError:
                    pass
                else:
                    logger.info('ping successful after {} seconds'.format(ping_attempt))
                    break
            else:
                raise PingTestFailedException('ping unsuccessful after {} seconds'.format(
                    ping_timeout))

    def _service_account_manage(self, **kwargs):
        user = kwargs['username']
        old_pwd = kwargs['old_password']
        new_pwd = kwargs['new_password']
        timeout = 60 if not kwargs.get('timeout') else kwargs.get('timeout')
        alias = "default" if not kwargs.get('alias') else kwargs.get('alias')
        self.factory.admin.change_ssh_password(username=user, new_password=new_pwd,
                                               old_password=old_pwd, timeout=timeout, connection=alias)
        dut_name = global_vars.alias_dut_dict.get(alias)
        if dut_name is not None:
            set_config_variable([dut_name, "password"], new_pwd)
            logger.info("new password {} updated in config dictionary".format(
                get_config_variable([dut_name, "password"])))
        else:
            logger.info("BTS section not found in global_vars. New password not updated in config "
                        "dictionary.")

    def _local_user_account_manage(self, **kwargs):
        old_username = kwargs['old_username']
        old_password = kwargs['old_password']
        new_username = kwargs.get('new_username')
        new_password = kwargs.get('new_password')
        delete_flag = kwargs.get('delete_flag', None)
        timeout = kwargs.get('timeout', 60)
        alias = kwargs.get('alias', "default")
        kwargs["should_pass"], kwargs["enable"] = True, True
        self.factory.admin.set_user_account(old_username=old_username, old_password=old_password,
                                            new_username=new_username, new_password=new_password,
                                            delete_flag=delete_flag, timeout=timeout, connection=alias)
        self._change_account_state(**kwargs)

    def _change_account_state(self, **kwargs):
        timeout = kwargs.get('timeout', 60)
        enable = kwargs['enable']
        account_type = kwargs['account_type']
        alias = kwargs.get('alias', "default")
        try:
            self.factory.admin.change_local_account_state(account_type=account_type,
                                                          enable=enable, timeout=timeout,
                                                          connection=alias)
        except Exception as error:
            if kwargs.get("should_pass"):
                logger.info("Change local account state error :: \n{0}".format(str(error)))
            else:
                raise Exception(error)

