    @contextmanager
    def _verify_successful_rollback(self, is_config_reset, alias):
        sw_info = self.factory.admin.get_software_info(connection=alias)
        passive_build_before_rollback = sw_info['Passive SW version']
        active_build_before_rollback = sw_info['Active SW version']
        logger.debug("passive_build_before_rollback: {}".format(passive_build_before_rollback))
        logger.debug("active_build_before_rolledback: {}".format(active_build_before_rollback))
        yield
        for i in range(24):
            if is_config_reset:
                time.sleep(120)
                break
            sw_info = self.factory.admin.get_software_info(connection=alias)
            passive_build_after_rollback = sw_info['Passive SW version']
            active_build_after_rollback = sw_info['Active SW version']
            logger.debug("passive_build_after_rollback: {}".format(passive_build_after_rollback))
            logger.debug("active_build_after_rolledback: {}".format(active_build_after_rollback))
            if passive_build_before_rollback == active_build_after_rollback:
                break
            time.sleep(200)
        else:
            if not passive_build_before_rollback == active_build_after_rollback:
                raise Exception("Rollback failed")
        logger.info("Roll back successful")

    def rollback_software(self, **kwargs):
        """Rollback software"""
        timeout = kwargs.get("timeout", 120)
        alias = kwargs.get("alias", "default")
