    def get_twamp_statistics(self, **kwargs):
        """Get twamp statistics"""
        twamp_id = kwargs.get("twamp_id", None)
        timeout = kwargs.get("timeout", 30)
        alias = kwargs.get("alias", "default")
        twamp_stats = self._get_all_twamp_session_stats_from_ute_admin(alias, timeout)
        return self._get_twamp_stat_for_twamp_id(twamp_id, twamp_stats)

    def _get_all_twamp_session_stats_from_ute_admin(self, alias, timeout):
        logger.debug("Getting all twamp session statistics ...")
        twamp_stats_list = self.factory.admin.get_twamp_statistics(connection=alias, timeout=timeout)
        logger.info(
            "All twamp session statistics :: \n{}".format(json.dumps(twamp_stats_list, indent=4,
                                                                     sort_keys=True)))
        return twamp_stats_list

    def _get_twamp_stat_for_twamp_id(self, twamp_id, twamp_stats):
        if not twamp_id:
            logger.debug("Returning all session details")
            return twamp_stats
        for twamp_session in twamp_stats:
            if str(twamp_session["twampId"]).strip() == str(twamp_id).strip():
                logger.debug("Returning statistics for twamp id :: {}".format(str(twamp_id)))
                return twamp_session
        else:
            BuiltIn().fail("TWAMP session with id {} does not exist".format(str(twamp_id)))

