    def change_ssh_access(self, **kwargs):
        """ Enables or Disables SSH Access
            :param enable: bool value to either enable or disable
            :param timeout: Time to wait for positive procedure result
            :param alias: Name of execution context
        """
        timeout = kwargs.get("timeout", 120)
        alias = kwargs.get("alias", 'default')
