    def change_ethernet_port_security(self, **kwargs):
        """ Enables or Disables ethernet port security
            :param enable: bool value to either enable or disable
            :param timeout: Time to wait for positive procedure result
            :param alias: Name of execution context
        """
        timeout = kwargs.get("timeout", 120)
        alias = kwargs.get("alias", 'default')
        enable = kwargs.get("enable", False)
        if enable is False:
            self.factory.admin.disable_ethernet_port_security(timeout=timeout, connection=alias)
        else:
            self.factory.admin.enable_ethernet_port_security(timeout=timeout, connection=alias)

