    def _create_read_only_account(self, **kwargs):
        """
        Create a read only account to log into web em

            account_type = "Btsread"
            enable = True
            alias = alias
            timeout = 60
            new_username = "newUsername"
            new_password = "newPassword"

        """

        account_type = "BtsRead"
        enable = True
        alias = kwargs.pop('alias', 'default')
        timeout = kwargs.pop('timeout', 60)

        # Enable read only mode
        self._change_account_state(account_type=account_type, enable=enable, timeout=timeout, alias=alias)

        # Create read only account

        new_username = kwargs["new_username"]
        new_password = kwargs["new_password"]
        old_username = "BTSRead"
        old_password = "nemuuser"
        delete_flag = False

        self.factory.admin.set_user_account(old_username=old_username, old_password=old_password,
                                            new_username=new_username, new_password=new_password,
                                            delete_flag=delete_flag, timeout=timeout, connection=alias)

    def change_bts_rad_parameters(self, **kwargs):
        params = kwargs.get("params")
        alias = kwargs.get('alias', 'default')
        dut = global_vars.alias_dut_dict[alias]
        component = kwargs.get("component", get_config_variable([dut, 'bts_id']))
        timeout = kwargs.get("timeout", 300)
        persistency = kwargs.pop("persistency", "not_persistent")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout", "params", "persistency", "alias"]}
        status_op = None
        if persistency.lower() == "not_persistent":
            status_op = self.factory.admin.change_bts_rad_parameters(component=component, params=params, timeout=timeout, alias=alias, **kwargs)
        elif persistency.lower() == "over_reset":
            status_op = self.factory.admin.change_bts_rad_parameters_with_overreset(component=component, params=params, timeout=timeout, alias=alias, **kwargs)
        elif persistency.lower() == "persistent":
            status_op = self.factory.admin.change_bts_rad_parameters_permanently(component=component, params=params, timeout=timeout, alias=alias, **kwargs)
        return status_op

    def get_bts_rad_parameters(self, **kwargs):
        parameters_type = kwargs.get("parameters_type")
        timeout = kwargs.get("timeout", 120)
