    def validate_scf(self, **kwargs):
        """
            Validate SCF with detected hardware or NIDD and relations.

            :param string scf_file: SCF file path
            :param string validation_type: DEPRECATED PARAMETER! possible values (NIDD_AND_RELATIONS, DETECTED_HW)
            :param boolean skip_parameter_relation_errors: Skip parameter relation errors
            :param Union[int,str] timeout: Time to wait for positive procedure result
            :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
            :param bool detailed_output: return full request response when True

            :return dict: SCF validation result or full API response detailed_output=True.

        """
        scf_file = kwargs["scf_file"]
        skip_parameter_relation_errors = kwargs.get("skip_parameter_relation_errors", False)
        detailed_output = kwargs.get("detailed_output", True)
        timeout = kwargs.get("timeout", 60)
        connection = kwargs.get("alias", "default")
        bts_id, scf_file = AdminBaseClass().get_scf_full_path(scf_file, connection)

        return self.factory.admin.validate_scf_online(scf_file,
                                                      skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                      detailed_output=detailed_output, timeout=timeout,
                                                      connection=connection)

