    def interface_mirroring(self, **kwargs):
        """
        Interface mirroring

        :param string interface: ["L1-L2"|"L2Hi-L2Lo"] mandatory, operator only configures it for operation 'Start'
        :param string destination: [Local"|"Remote] mandatory, operator only configures it for operation 'Start'
        :param int mirroring_time: [0, 2147483647] seconds mandatory, operator only configures it for operation 'Start'
        :param string operation: ["Start"|"Stop"] mandatory
        :param list nr_cell_dns: optional, operator only configures it for operation 'Start', operator can select up to 8 NR cells
        :param Union[int,str] timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :param AdminConnection connection: AdminConnection.

        :return dict: Procedure feedback.

        """

        operation = kwargs["operation"]
        interface = kwargs["interface"]
        destination = kwargs["destination"]
        mirroring_time = kwargs["mirroring_time"]
        nr_cell_dns = kwargs.get("nr_cell_dns", None)
        timeout = kwargs.get("timeout", 60)
        detailed_output = kwargs.get("detailed_output", False)
        connection = kwargs.get("alias", "default")
        return self.factory.admin.interface_mirroring(operation.capitalize(), interface=interface,
                                                      destination=destination, mirroring_time=mirroring_time,
                                                      nr_cell_dns=nr_cell_dns, timeout=timeout,
                                                      detailed_output=detailed_output, connection=connection)

